"use strict";(globalThis.webpackChunkgrc||=[]).push([[18752],{64352(e){e.exports=JSON.parse('{"citeKey":"kougkas2016leveragingburst","slug":"kougkas-2016-leveraging-burst-85be","title":"Leveraging Burst Buffer Coordination to Prevent I/O Interference","authors":["A. Kougkas","M. Dorier","R. Latham","R. Ross","X.-H. Sun"],"venue":"The eScience\'16, Baltimore, Maryland, USA2016, pp. 371-380","type":"Conference","entryType":"inproceedings","date":"October, 2016","year":2016,"era":"iit","month":10,"doi":"10.1109/escience.2016.7870922","abstract":"Concurrent accesses to the shared storage resources in current HPC machines lead to severe performance degradation caused by I/O contention. In this study, we identify some key challenges to efficiently handling interleaved data accesses, and we propose a system-wide solution to optimize global performance. We implemented and tested several I/O scheduling policies, including prioritizing specific applications by leveraging burst buffers to defer the conflicting accesses from another application and/or directing the requests to different storage servers inside the parallel file system infrastructure. The results show that we mitigate the negative effects of interference and optimize the performance up to 2x depending on the selected I/O policy.","hasAbstract":true,"lede":"In this study, we identify some key challenges to efficiently handling interleaved data accesses, and we propose a system-wide solution to optimize global performance.","links":{"pdf":"https://grc.iit.edu/papers/2016/kougkas-2016-leveraging-burst-85be.pdf","slides":"https://grc.iit.edu/papers/2016/kougkas-2016-leveraging-burst-85be-slides.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["hermes"],"memberAuthors":["kougkas-anthony","sun-xian-he"]}')}}]);